using System.IO.Ports;
var builder=WebApplication.CreateBuilder(args); builder.Services.AddSingleton<Store>(); builder.Services.AddHostedService<SerialWorker>(); var app=builder.Build(); app.UseDefaultFiles(); app.UseStaticFiles(); app.MapGet("/api/telemetry",(Store s)=>Results.Ok(s.Snapshot())); app.Run();
public sealed class Store { private readonly object gate=new(); private int raw=3268; public void Set(int v){lock(gate){raw=Math.Clamp(v,0,4095);}} public object Snapshot(){lock(gate){var pct=Math.Round(raw/4095d*100,1);return new {sensor="ESP32-Potentiometer",rawValue=raw,voltage=Math.Round(raw/4095d*3.3,2),percentage=pct,alertLevel=pct>=90?"DANGER (HIGH)":pct>=75?"WARNING":"NORMAL",dataSource="Live Hardware (serial)"};}}}
public sealed class SerialWorker:BackgroundService { readonly Store store; public SerialWorker(Store s)=>store=s; protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){var ports=SerialPort.GetPortNames();var port=ports.FirstOrDefault(p=>!p.Equals("COM1",StringComparison.OrdinalIgnoreCase));if(port!=null)try{using var sp=new SerialPort(port,115200){ReadTimeout=500};sp.Open();while(sp.IsOpen&&!ct.IsCancellationRequested){if(int.TryParse(sp.ReadLine().Trim(),out var v))store.Set(v);}}catch{}else{store.Set((int)((Math.Sin(DateTime.UtcNow.TimeOfDay.TotalSeconds*.8)+1)*2047.5));}await Task.Delay(100,ct);}}}